vt[vt.length]=`<div id="text_86" class="textshirt mergershirt" style="top: 44px; left: 88px; font-size: 26px;"></div>`;
vt[vt.length]=`<div id="text_83" class="textshirt mergershirt" style="width: 359px; white-space: normal; top: 56px; left: 88px; height: 360px;">„Okay, die Filmliste des Hubs ist verfügbar“, verkündete Chloe und ergriff die Fernbedienung.<br> „Wir haben drei Optionen: *‚Liebe in Zeiten von Sonneneruptionen‘* – eine Romanze; *‚Der Chromschatten‘* – ein Thriller; <br> oder *‚Der Fall der grübelnden Chiffre‘* – eine Detektivgeschichte.“<br class=""><br> Die Stirnbänder wurden wieder angelegt.<br> „Romanze“, sagte Anya, woraufhin der Hub ein sanftes, wehmütiges Blau von ihr und ein mildes, tolerantes Grün von Leo registrierte. <br> Bei Chloe zeigte sich ein flaches, graues Desinteresse.<br><br> „Thriller“, schlug Leo vor. Ein plötzlicher Ausschlag in aufgeregtem Bernstein von ihm, ein kurzes Aufleuchten von stressigem Orange bei Anya und ein ähnlicher, wenn auch schwächerer Ausschlag bei Chloe.</div>`;
vt[vt.length]=`<div id="text_84" class="textshirt mergershirt" style="width: 363px; white-space: normal; top: 61px; left: 528px; height: 360px;">„Ein Detektivroman“, sagte Chloe. „Ein Rätsel, das den Geist anregt.“<br> Diesmal fielen die Messwerte anders aus. Ein intensives, fokussiertes Indigoblau bei Chloe. Ein beständiges, aufmerksames Grün bei Leo.<br> Und bei Anya ein überraschendes, helles Blau, das von echter Neugier zeugte.<br><br> Der Hub gab ein Signal von sich. Das Ergebnis erschien:<br><br> **OPTIMALE WAHL: DER FALL DER KOGITATIVEN CHIFFRE.**<br><br> *Begründung: Höchster gemeinsamer Wert für das Interesse der Beteiligten.<br> Das Detektivgenre regt den kollektiven Instinkt zur Problemlösung an, ohne dabei jene Stressreaktionen auszulösen, die oft mit Thrillern einhergehen.<br> Die Liebesgeschichte wurde als zu kontrovers eingestuft.*</div>`;
vte[vte.length]=`<div id="text_86" class="textshirt mergershirt`+transws+`" style="top: 44px; left: 88px; font-size: 26px;"></div>`;
vte[vte.length]=`<div id="text_83" class="textshirt mergershirt`+transws+`" style="width: 359px; white-space: normal; top: 56px; left: 88px; height: 360px;">"Okay, the Hub's movie list is up," Chloe announced, taking charge of the remote.<br> "We have three options: *'Love in the Time of Solar Flares'*, a romance; *'The Chrome Shadow'*, a thriller; <br> or *'The Case of the Cogitative Cipher'*, a detective story."<br class=""><br> The headbands went on again.<br> "Romance," Anya said, and the Hub registered a gentle, wistful blue from her and a mild, tolerant green from Leo. <br> Chloe’s reading was a flat, grey disinterest.<br><br> "Thriller," Leo proposed. A spike of excited amber from him, a flicker of stress-orange from Anya, and a similar, though smaller, spike from Chloe.</div>`;
vte[vte.length]=`<div id="text_84" class="textshirt mergershirt`+transws+`" style="width: 363px; white-space: normal; top: 61px; left: 528px; height: 360px;">"Detective story," Chloe said. "A mind-stimulating puzzle."<br class=""> This time, the readings were different. A sharp, focused indigo from Chloe. A steady, engaged green from Leo. <br> And from Anya, a surprising, bright blue of genuine curiosity.<br><br> The Hub chimed. The verdict appeared:<br><br> **OPTIMAL CHOICE: THE CASE OF THE COGITATIVE CIPHER.**<br><br> *Rationale: Highest shared engagement score.<br>  The detective genre stimulates collective problem-solving instincts without triggering the stress responses associated with the thriller.<br> The romance was deemed too divisive.*</div>`;
dbset[dbset.length] = {dbbg:dbbg,dbbtn:dbbtn,vt:vt,vte:vte};

